

# This file was *autogenerated* from the file sagemath/check/048_claim_A_theta_tilde/check_03_eigen_and_diagonalization.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0p0 = RealNumber('0.0'); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_1en9 = RealNumber('1e-9')# ---------------------------------------------------------
# SageMath: A(theta~_mu) の固有値・固有ベクトルと対角化
# 対象: structured-latex eigenvector_of_A_theta_tilde, diagonalization_check_P_D
#   (1) 特性多項式 lambda^2 - 2 gamma_1 lambda + (gamma_1^2 + gamma_2 gamma_2(-)) = 0 の解が
#       lambda_{pm} = gamma_1 pm sqrt(-gamma_2(theta~) gamma_2(-theta~)) = gamma_1 pm |gamma_2|
#   (2) v_{pm} = (mp |gamma_2|, gamma_2(-theta~)) が A v = lambda v を満たす
#   (3) checkP_mu（008 章の P_mu と同じ正規化 c = 1/(2 sqrt(M) gamma_2(-theta~))）について
#       det checkP_mu = -|gamma_2| / (2 M gamma_2(-theta~)) != 0 かつ A = checkP checkD checkP^{-1}
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '_prelude.sage'))

print("=== 固有値・固有ベクトル・対角化 ===")
all_ok = True
for (K1, K2) in K_CASES:
    P = coeffs(K1, K2)
    w = {'char': _sage_const_0p0 , 'sqrt': _sage_const_0p0 , 'eigp': _sage_const_0p0 , 'eigm': _sage_const_0p0 , 'detP': _sage_const_0p0 ,
         'diag': _sage_const_0p0 , 'spec': _sage_const_0p0 }
    detP_min = None
    for M in M_CASES:
        for mu in range(_sage_const_1 , M + _sage_const_1 ):
            t = th_tilde(M, mu)
            a = g2(t, P)
            b = g2(-t, P)
            r = RDF(abs(a))
            u = g1(t, P)
            A = A_mat(t, P)

            s = sqrt_cc(clean_real(-a * b))         # = |gamma_2|
            w['sqrt'] = max(w['sqrt'], abs(s - r))
            lp = u + s
            lm = u - s

            # (1) 特性方程式
            for lam in (lp, lm):
                w['char'] = max(w['char'], abs(lam ** _sage_const_2  - _sage_const_2  * u * lam + (u ** _sage_const_2  + a * b)))
            # 実際の固有値集合との一致
            ev = sorted([CDF(z) for z in A.eigenvalues()], key=lambda z: -z.real())
            w['spec'] = max(w['spec'], abs(ev[_sage_const_0 ] - lp), abs(ev[_sage_const_1 ] - lm))

            # (2) 固有ベクトル
            vp = vector(CDF, [-r, b])
            vm = vector(CDF, [r, b])
            w['eigp'] = max(w['eigp'], (A * vp - lp * vp).norm())
            w['eigm'] = max(w['eigm'], (A * vm - lm * vm).norm())

            # (3) checkP, checkD
            sm = RDF(M).sqrt()
            cP = matrix(CDF, [[-r / (_sage_const_2  * sm * b), r / (_sage_const_2  * sm * b)],
                              [_sage_const_1  / (_sage_const_2  * sm), _sage_const_1  / (_sage_const_2  * sm)]])
            cD = matrix(CDF, [[lp, _sage_const_0 ], [_sage_const_0 , lm]])
            d = cP.det()
            w['detP'] = max(w['detP'], abs(d - (-r / (_sage_const_2  * M * b))))
            detP_min = abs(d) if detP_min is None else min(detP_min, abs(d))
            w['diag'] = max(w['diag'], (A - cP * cD * cP.inverse()).norm())

    worst = max(w.values())
    ok = worst <= _sage_const_1en9  and detP_min > _sage_const_1en9 
    all_ok = ok and all_ok
    print(f"  {case_label(K1, K2)}: 特性式 {w['char']:.1e}, sqrt {w['sqrt']:.1e}, "
          f"固有ベクトル(+) {w['eigp']:.1e} (-) {w['eigm']:.1e}, 固有値集合 {w['spec']:.1e}, "
          f"det式 {w['detP']:.1e}, min|det checkP| {float(detP_min):.2e}, "
          f"対角化 {w['diag']:.1e} -> {'PASS' if ok else 'FAIL'}")

print("RESULT: PASS" if all_ok else "RESULT: FAIL")
if not all_ok:
    import sys
    sys.exit(_sage_const_1 )

